var oneLayerProducts;
var shoptetContext = getShoptetContext();
var projectId = String(shoptetContext.projectId || "");
var productId = shoptetContext.productId;
var language2 = projectId === "704436" ? "cs" : shoptetContext.language;
if ($(".type-product")[0]) {
  twoLayersProducts = productId == 601 || productId == 604 || productId == 607;
  boxsParameterIds2 = [94, 97, 104];
  oneLayerProducts = productId == 598 || productId == 610 || productId == 613;
  if (projectId === "581408") {
    $(".custom-footer__banner10").hide();
    twoLayersProducts = productId == 2406 || productId == 2409 || productId == 2412;
    oneLayerProducts = productId == 2403 || productId == 2415 || productId == 2418;
    boxsParameterIds2 = [66, 69, 78, 104];
  }
}
var ButtonUtils = {
  /**
   * Creates HTML for price display
   * @param {number} price - Base price
   * @param {number} save - Amount saved
   * @param {boolean} prefix - Whether to show "od" prefix
   * @returns {string} HTML string for price display
   */
  /**
   * @param {number} price - selling price (čo zákazník platí)
   * @param {number} save  - úspora oproti doporučenej cene (full - price)
   * @param {boolean} prefix - prefixová "od" varianta (napr. boxy)
   *
   * Klient: „doporučená cena stále chýba" – pripojíme prečiarknutú
   * doporučenú cenu (`price + save`) vedľa selling ceny, len keď je
   * úspora > 0 (inak by sme videli rovnakú cenu dvakrát).
   */
  createPriceHTML: (price2, save, prefix) => {
    const recommended = Number(price2) + Number(save);
    const showRecommended = Number(save) > 0 && recommended > Number(price2);
    const recommendedHTML = showRecommended ? `<span class="price-recommended" data-recommended="${recommended}">${NumToPrice(recommended)}</span>` : "";
    if (prefix) {
      return `<div class="price">od ${NumToPrice(price2)} ${recommendedHTML}</div><div class="save" data-save="${save}">U\u0161etr\xEDte a\u017E ${NumToPrice(save)}</div>`;
    }
    return `<div class="price">${NumToPrice(price2)} ${recommendedHTML}</div><div class="save" data-save="${save}">U\u0161etr\xEDte ${NumToPrice(save)}</div>`;
  },
  /**
   * Determines button type class
   * @param {string} type - Button type
   * @param {string|number} value - Button value
   * @returns {string} CSS class for button type
   */
  getButtonTypeClass: (type, value) => {
    if (type === "config" && value == 0) return "none";
    if (value === "89-2225") return "radio none";
    return type;
  }
};
function createSlug(text) {
  return String(text).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^\w\s-]/g, "").trim().replace(/\s+/g, "-").replace(/-+/g, "-");
}
function createUpsaleButton(img, text, position, value, type, price2, prefix, texts) {
  if (!img || !text || !position) return;
  const priceParts = String(price2 || "0/0").split("/");
  const base = Number(priceParts[0]);
  const full = Number(priceParts[1] || 0);
  const save = full - base;
  const typeClass = ButtonUtils.getButtonTypeClass(type, value);
  const buttonHTML = `
    <div class="upsale-button ${typeClass}" value="${value}">
      <img src="${img}?7" alt="${text}" />
      <div class="banner-header"><span>${text}</span></div>
    </div>
  `;
  const button = $(buttonHTML).appendTo(position);
  if (base > 0) {
    const priceHTML = ButtonUtils.createPriceHTML(base, save, !!prefix).replace(
      /Ušetríte/,
      texts && texts.you_will_save ? texts.you_will_save : "U\u0161etr\xEDte"
    );
    $(button).find(".banner-header").append(priceHTML);
  }
  $(".upsale-Banner").hide();
  setTimeout(() => {
    $(".parameter-wrap.orders-1").removeClass("goToAction");
  }, 1e3);
}
