      const $img = $("<img>", { src: image2 }).appendTo(imageWrap);
      const remeasure = () => {
        if (window.__lcdMeasureStep) $wrap.each((_, el) => window.__lcdMeasureStep(el));
      };
      requestAnimationFrame(remeasure);
